def layers_for(area, subdir, civ4_root):
	# <!-- custom: Compare the installed asset layers oldest first; compare C++ with Civ4CE's Firaxis SDK copies.
	# An explicit install root also works for checkouts outside the Mods directory. (Claude code Opus 5.5 + GPT-6.2-Sol) -->
	# <!-- custom: The layers stop at the base game and base AdvCiv (the upstream Git ref).
	# AdvCiv already holds what it took from K-Mod, Better BTS AI and BUG, and the audit's "came with K-Mod" events show that provenance; what AdvCiv left out of those mods was its decision, not SAS's.
	# To look for a feature AdvCiv did not take, add a K-Mod or BUG tree as an extra layer the same way (the user, 2026-11-22). (Claude code Opus 5.5) -->
	if area == "cpp":
		sdk = civ4_root / BTS_DIR / "Mods" / "Civ4CE-main"
		return tuple((name, sdk / folder / subdir) for name, folder in (("vanilla", "Civ4"), ("warlords", "Warlords"), ("bts", "BtS")))
	return tuple((name, civ4_root / folder / subdir) for name, folder in (("vanilla", ""), ("warlords", "Warlords"), ("bts", BTS_DIR)))


def file_key(path, root, by_name):
	if by_name:
		return path.name.lower()
	return path.as_posix().lower().removeprefix(root.as_posix().lower() + "/")


def area_files(root, suffixes, by_name):
	# <!-- custom: Compare Python modules by basename as Civ4's flat game-script imports do.
	# Compare XML and C++ by relative path.
	# Keys are lower case, as Windows paths are. (Claude code Opus 5.5) -->
	files = {}
	if root.is_dir():
		for path in root.rglob("*"):
			if path.is_file() and (suffixes is None or path.suffix.lower() in suffixes):
				files.setdefault(file_key(path, root, by_name), path)
	return files


def text_hash(path):
	# <!-- custom: Line endings differ between the layers and our checkout (KI#1097), so hash with them normalized. (Claude code Opus 5.5) -->
	return hashlib.sha256(path.read_bytes().replace(b"\r\n", b"\n")).hexdigest()[:16]


def asset_hash(area, path):
	return asset_bytes_hash(area, path.read_bytes())


def asset_bytes_hash(area, data):
	# <!-- custom: res includes fonts, cursors and textures.
	# Hash their bytes as stored; newline normalization is for source and Config text. (GPT-6.2-Sol) -->
	if area == "res":
		return hashlib.sha256(data).hexdigest()[:16]
	return hashlib.sha256(data.replace(b"\r\n", b"\n")).hexdigest()[:16]


@lru_cache(maxsize=None)
def repo_area_paths(subdir, suffixes):
	# <!-- custom: Include review additions and tracked files that still exist.
	# Git's excludes drop local build headers.
	# Match directory casing independently of the host because the repo tracks Assets/Res and the game installs it as Assets/res. (GPT-6.2-Sol) -->
	output = subprocess.run(["git", "ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", ":(icase)" + subdir], cwd=REPO, capture_output=True, check=True).stdout
	paths = {REPO / name for name in output.decode("utf-8").split("\0") if name}
	return sorted(path for path in paths if path.is_file() and (suffixes is None or path.suffix.lower() in suffixes))


def sas_files(area, subdir, suffixes):
	files = {}
	for path in repo_area_paths(subdir, suffixes):
		files.setdefault(file_key(path, REPO / subdir, area == "python"), path)
	return files


def sas_carries(row, sas):
	# <!-- custom: True when SAS keeps the inherited filename: a file at the same path, or for Python a file of the same name in any folder, as Civ4 imports modules by name.
	# It says nothing about content: SAS may have rewritten the file entirely or taken it from another mod, as with CIV4ProcessInfo.xml from Realism Invictus.
	# The audit first said SAS "carries" such a file, which the user found misleading for that reason (2026-11-22); the function name stays, the wording everywhere it shows is "kept filename", as "name" in Civ4 can also mean a text key or an asset name. (Claude code Opus 5.5) -->
	return row["file"] in sas


def comparison_sources(area, subdir, suffixes, civ4_root):
	# <!-- custom: The local install supplies the three Civ4 layers.
	# Base AdvCiv is read from Git.
	# Some layers genuinely have no res or Config folder. (GPT-6.2-Sol) -->
	layers = layers_for(area, subdir, civ4_root)
	for name, root in layers:
		if suffixes is not None and not root.is_dir():
			raise SystemExit("missing %s layer: %s; verify --civ4-root and the Civ4CE SDK checkout" % (name, root))
	return layers


TSV_COLUMNS = ("path", "layers", "advcivEvents", "otherPaths")
# <!-- custom: The local branch holding upstream AdvCiv's own history, the version SAS last merged; its commits are K-Mod's and AdvCiv's, never rewritten, so their SHAs stay valid in a tracked list, while SAS's own commits are left out, as our history gets rewritten (the user, 2026-11-22).
# It was "1.14" written here; advciv_release now finds the newest release branch already merged into HEAD, when a command needs it, so a newer AdvCiv needs no edit once merged; --upstream-ref overrides it.
# Resolving it only when needed, with a clear error when there is none, follows Codex's review (2026-11-22). (Claude code Opus 5.5 + GPT-6.2-Sol) -->


def upstream_events(ref):
	output = subprocess.run(["git", "log", "--reverse", "--topo-order", "--full-history", "--no-merges", "--diff-filter=ADR", "-M", "--abbrev=10", "--format=%x1e%as %h", "--name-status", "-z", ref, "--", *(":(icase)" + subdir for _, subdir, _ in AREAS)], cwd=REPO, capture_output=True, text=True, encoding="utf-8", errors="replace", check=True).stdout
	return parse_upstream_events(output)


def parse_upstream_events(output):
	# <!-- custom: Keep each operation's index, so a rename only follows events that actually preceded it.
	# Strip Git's leading newline from the first status in each commit. (Claude code Opus 5.5 + GPT-6.2-Sol) -->
	events = {}
	order = 0
	for record in output.split("\x1e")[1:]:
		header, *fields = record.rstrip("\0").split("\0")
		names = iter(fields)
		for status in names:
			code = status.strip()[0]
			path = next(names)
			key = path.lower()
			order += 1
			if code == "R":
				destination = next(names)
				destination_key = destination.lower()
				if key != destination_key:
					events.setdefault(key, []).append((order, "out", None, "%s renamed to %s" % (header, destination)))
				text = "%s renamed from %s to %s" % (header, path, destination)
				events.setdefault(destination_key, []).append((order, "in", key, text))
			else:
				action = "added" if code == "A" else "deleted"
				events.setdefault(key, []).append((order, action, None, "%s %s" % (header, action)))
	return events


def file_history(events, path):
	# <!-- custom: Include each incarnation at the requested path.
	# Follow incoming renames only as far back as the source file's own lifetime before that rename.
	# This keeps a reused path's later events out and lets A -> B -> A retain both moves. (GPT-6.2-Sol) -->
	story = {}
	pending = [(path.lower(), None)]
	while pending:
		key, before = pending.pop()
		for order, action, previous, text in reversed(events.get(key, ())):
			if before is not None:
				if order >= before:
					continue
				if action in ("deleted", "out"):
					break
			if action == "in":
				story[order] = text
				if previous != key:
					pending.append((previous, order))
			else:
				story.setdefault(order, text)
	return "; ".join(story[order] for order in sorted(story)) or "-"


def upstream_paths(ref):
	# <!-- custom: ls-tree lacks an icase pathspec.
	# Read the ref once and filter its canonical paths in Python, rather than reading the mutable Mods/AdvCiv directory. (Claude code Opus 5.5 + GPT-6.2-Sol) -->
	revision = subprocess.run(["git", "rev-parse", "--verify", "--quiet", ref + "^{commit}"], cwd=REPO, capture_output=True, text=True)
	if revision.returncode:
		raise SystemExit("missing upstream AdvCiv commit %s; pass --upstream-ref" % ref)
	commit = revision.stdout.strip()
	output = subprocess.run(["git", "ls-tree", "-r", "--name-only", "-z", commit], cwd=REPO, capture_output=True, text=True, encoding="utf-8", check=True).stdout
	return commit, output.rstrip("\0").split("\0")


def upstream_files(paths, area, subdir, suffixes):
	root = Path(subdir)
	prefix = subdir.lower() + "/"
	files = {}
	for name in sorted(paths):
		if name.lower().startswith(prefix) and (suffixes is None or Path(name).suffix.lower() in suffixes):
			files.setdefault(file_key(Path(name), root, area == "python"), name)
	return files


def write_tsv(civ4_root, upstream_ref):
	# <!-- custom: One row per inherited file: its full path as the newest layer providing it ships it, the layers that ship it, when it entered base AdvCiv's lineage, and any layer keeping it at another path.
	# Earlier versions repeated the same path in a column per tree (four times for CvMapGeneratorUtil.py), split it from a separate area column, and stored hashes nothing used and SAS's own status, which changes too often for upstream data (the user, 2026-11-22).
	# These change only when the base game or base AdvCiv do. (Claude code Opus 5.5) -->
	commit, upstream = upstream_paths(upstream_ref)
	events = upstream_events(commit)
	lines = ["\t".join(TSV_COLUMNS)]
	for area, subdir, suffixes in AREAS:
		layers = comparison_sources(area, subdir, suffixes, civ4_root)
		files = dict((name, dict((key, subdir + "/" + path.relative_to(root).as_posix()) for (key, path) in area_files(root, suffixes, area == "python").items())) for (name, root) in layers)
		files["advciv"] = upstream_files(upstream, area, subdir, suffixes)
		for key in sorted(set().union(*files.values())):
			present = [(name, files[name][key]) for name in TREES if key in files[name]]
			path = present[-1][1]
			others = ";".join("%s:%s" % (name, other) for (name, other) in present if other != path) or "-"
			advciv_events = file_history(events, path)
			lines.append("\t".join((path, ",".join(name for (name, _) in present), advciv_events, others)))
	TSV.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
	print("wrote %s (%d files)" % (TSV.relative_to(REPO).as_posix(), len(lines) - 1))


def path_area(path):
	lowered = path.lower()
	for area, subdir, suffixes in AREAS:
		if lowered.startswith(subdir.lower() + "/") and (suffixes is None or Path(path).suffix.lower() in suffixes):
			return (area, subdir)
	raise ValueError("inherited_files.tsv path outside the audited areas: " + path)


def read_tsv():
	# <!-- custom: Each row also gets its area and lookup key, derived from its path, as the checks match files: a Python module by its lower-case name, as Civ4 imports it, other files by their lower-case path in the area. (Claude code Opus 5.5) -->
	rows = []
	seen = set()
	lines = TSV.read_text(encoding="utf-8").splitlines()
	if not lines or tuple(lines[0].split("\t")) != TSV_COLUMNS:
		raise ValueError("unexpected inherited_files.tsv header")
	for number, line in enumerate(lines[1:], 2):
		cells = line.split("\t")
		if len(cells) != len(TSV_COLUMNS):
			raise ValueError("unexpected inherited_files.tsv columns on line %d" % number)
		row = dict(zip(TSV_COLUMNS, cells))
		area, subdir = path_area(row["path"])
		key = file_key(Path(row["path"]), Path(subdir), area == "python")
		if (area, key) in seen:
			raise ValueError("duplicate inherited_files.tsv key on line %d: %s" % (number, row["path"]))
		seen.add((area, key))
		rows.append(dict(row, area=area, file=key))
	return rows


def in_base_game(row):
	return any(name in row["layers"].split(",") for name in BASE_TREES)


def base_game_path(row):
	layer = next(name for name in reversed(row["layers"].split(",")) if name in BASE_TREES)
	paths = dict(item.split(":", 1) for item in row["otherPaths"].split(";") if ":" in item)
	return paths.get(layer, row["path"])


def module_imports(text):
	# <!-- custom: Tokenize Python 2.4 syntax so aliases, continuations and conditional imports keep their module names, while comments and docstrings cannot create dependencies.
	# The check records static absolute imports; Civ4 and inherited modules can load other files themselves. (GPT-6.2-Sol) -->
	tokens = list(tokenize.generate_tokens(StringIO(text).readline))
	from_import = False
	plain_import = False
	expect_module = False
	for index, token in enumerate(tokens):
		if token.type == tokenize.NEWLINE or token.string == ";":
			from_import = plain_import = expect_module = False
		elif token.type == tokenize.NAME and token.string == "from":
			from_import = True
			following = tokens[index + 1]
			if following.type == tokenize.NAME:
				yield following.string.lower()
		elif token.type == tokenize.NAME and token.string == "import":
			if from_import:
				from_import = False
			else:
				plain_import = expect_module = True
		elif plain_import and token.string == ",":
			expect_module = True
		elif expect_module and token.type == tokenize.NAME:
			yield token.string.lower()
			expect_module = False


def imported_modules(paths):
	found = {}
	for path in paths:
		for module in module_imports(path.read_text(encoding="latin-1")):
			found.setdefault(module, set()).add(path.stem)
	return found


def python_importers(sas_python):
	# <!-- custom: PrivateMaps and SASPilot/game also run inside Civ4.
	# Scan their imports without treating those entrypoints as general Assets/Python modules. (GPT-6.2-Sol) -->
	paths = list(sas_python.values())
	for folder in ("PrivateMaps", "SASPilot/game"):
		paths.extend(repo_area_paths(folder, (".py",)))
	return imported_modules(paths)


def audit_key(area, subdir, key):
	# <!-- custom: How the audit names a file: a Python module by its name, as Civ4 imports it, other files by their path. (Claude code Opus 5.5) -->
	return key if area == "python" else subdir + "/" + key


def new_sas_files(area, subdir, suffixes, tsv_rows):
	# <!-- custom: Files SAS has that neither the base game nor base AdvCiv provides, found from the tree and the tsv alone, so CI can keep the audit current without Civ4 (the user, 2026-11-22). (Claude code Opus 5.5) -->
	inherited = {row["file"] for row in tsv_rows if row["area"] == area}
	return [path for path in repo_area_paths(subdir, suffixes) if file_key(path, REPO / subdir, area == "python") not in inherited]


def generated_bounds(text):
	if text.count(GENERATED_START) != 1 or text.count(GENERATED_END) != 1:
		raise ValueError("expected one start and one end marker for the generated tables")
	start = text.index(GENERATED_START)
	end = text.index(GENERATED_END)
	if end <= start:
		raise ValueError("generated tables end marker precedes the start marker")
	return start, end + len(GENERATED_END)


# <!-- custom: Headings of the audit's generated file lists, shared with the helper that writes them so the hand-written part can link them by name. (Claude code Opus 5.5) -->
TAKEN_IN_HEADING = "Files taken in from the base game"
DROPPED_HEADING = "Files taken in and dropped again"
REMOVED_HEADING = "Files removed or renamed from base AdvCiv"
IMPORTED = "imported by SAS"
NOT_IMPORTED = "no static SAS import"


def inherited_imports(tsv_rows):
	# <!-- custom: Returns (inherited modules SAS imports, problems): modules SAS has no module of the same name for but imports, and imports found in none of SAS, the base game or the Python 2.4 runtime. (Claude code Opus 5.5) -->
	sas_python = sas_files("python", "Assets/Python", (".py",))
	inherited = {row["file"][:-3] for row in tsv_rows if row["area"] == "python" and row["file"] not in sas_python and in_base_game(row)}
	imported = set()
	problems = []
	for (module, importers) in sorted(python_importers(sas_python).items()):
		if module + ".py" in sas_python:
			continue
		if module in inherited:
			imported.add(module)
		elif module not in PY24_RUNTIME_MODULES | OPTIONAL_IMPORTS:
			problems.append("%s imports %s, which is neither in SAS or the base game nor listed as a Python 2.4 runtime or optional module" % (", ".join(sorted(importers)), module))
	return (imported, problems)


# <!-- custom: Base-game Python modules SAS's code imports without carrying a copy, each with why it may stay in the base game; any other one fails, as SAS keeps the base-game modules it uses (KI#1104), and an entry nothing imports any more fails too.
# The user asked that the rule be enforced, not only written (2026-11-22). See KI#1104. (Claude code Opus 5.5) -->
NOT_CARRIED = {
	"techtree": "CvForeignAdvisor.py constructs it and nothing then reads the stored object",
	"cvpediamain": "CvScreensInterface.py imports it only when BUG's Sevopedia option is off, to show the old Civilopedia; whether SAS carries that fallback is undecided",
	"cvpediahistory": "imported beside CvPediaMain for the same fallback",
}


def not_carried_problems(imported):
	problems = []
	for module in sorted(imported - set(NOT_CARRIED)):
		problems.append("SAS imports the base-game module %s without carrying it; copy it with python LLM_Helpers/code_history/inherited_files.py --take-in <path>, or list why in NOT_CARRIED (KI#1104)" % module)
	for module in sorted(set(NOT_CARRIED) - imported):
		problems.append("NOT_CARRIED lists %s, which SAS no longer imports from the base game; drop the entry" % module)
	return problems


def text_name_problems(tsv_rows):
	# <!-- custom: A SAS text file named like a base-game one replaces it, so every key only that file defines stops loading; K-Mod's LoadGlobalText drops the base copy of a same-named file. SAS's own names never matched one when this was added (2026-11-22). See KI#1104. (Claude code Opus 5.5) -->
	base = {Path(row["path"]).name.lower(): row["path"] for row in tsv_rows if row["path"].lower().startswith("assets/xml/text/") and in_base_game(row)}
	return ["Assets/XML/Text/%s has the name of the base game's %s, so it replaces that file and drops the keys only it defines; rename it (KI#1104)" % (path.name, base[path.name.lower()]) for path in sorted((REPO / "Assets" / "XML" / "Text").glob("*.xml")) if path.name.lower() in base]


def carried_inherited(tsv_rows):
	# <!-- custom: Fingerprint the upstream key and every SAS path carrying it.
	# A move can preserve a Python basename, but it still changes which file the audit describes.
	# SAS-only paths do not enter this fingerprint. (GPT-6.2-Sol) -->
	carried = []
	for area, subdir, suffixes in AREAS:
		inherited = {row["file"]: row["path"] for row in tsv_rows if row["area"] == area}
		for path in repo_area_paths(subdir, suffixes):
			key = file_key(path, REPO / subdir, area == "python")
			if key in inherited:
				carried.append(inherited[key] + "\t" + path.relative_to(REPO).as_posix())
	return sorted(carried)


def audit_markers(tsv_rows, imported):
	# <!-- custom: Fingerprints the audit's generated part records, so CI can tell it is stale without storing SAS's file list anywhere: the inherited list it came from, the inherited filenames SAS keeps, and the inherited Python modules SAS imports.
	# Adding, removing or moving a SAS copy changes the second fingerprint.
	# Starting or stopping an inherited import changes the third.
	# A first version tracked a full per-file inventory TSV for this, which would churn with every SAS change and every history rewrite; the user preferred the generated report in LLM_Helpers/outputs (2026-11-22).
	# A second fingerprinted every SAS file, so most feature commits, adding a module of SAS's own, would have had to regenerate the audit for a count; only decisions about inherited files are worth that (2026-11-22). (Claude code Opus 5.5) -->
	def digest(values):
		return hashlib.sha256("\n".join(values).encode("utf-8")).hexdigest()[:16]
	return ["<!-- inherited_files.tsv %s -->" % text_hash(TSV), "<!-- inherited filenames SAS keeps %s -->" % digest(carried_inherited(tsv_rows)), "<!-- inherited Python imports %s -->" % digest(sorted(imported))]


def check():
	problems = []
	rows = read_tsv()
	audit_text = AUDIT.read_text(encoding="utf-8")
	try:
		start, end = generated_bounds(audit_text)
	except ValueError as error:
		return [str(error)]
	lines = audit_text[start:end].splitlines()
	(imported, import_problems) = inherited_imports(rows)
	problems += import_problems
	problems += not_carried_problems(imported)
	problems += text_name_problems(rows)
	reasons = ("inherited_files.tsv changed", "SAS started or stopped keeping an inherited filename, or moved its file", "SAS started or stopped importing an inherited Python module")
	for (marker, reason) in zip(audit_markers(rows, imported), reasons):
		if marker not in lines:
			problems.append("the inherited files audit is stale: %s; run python LLM_Helpers/code_history/inherited_files.py --inventory and review the audit" % reason)
	return problems


def main():
	parser = argparse.ArgumentParser(description="Check that SAS's copies of base-game files and its inherited Python imports match the inherited files audit.")
	parser.add_argument("--write", action="store_true", help="rebuild inherited_files.tsv from the local Civ4 install")
	parser.add_argument("--civ4-root", type=Path, default=DEFAULT_CIV4_ROOT, help="install root containing Assets and Beyond the Sword (used with --write)")
	parser.add_argument("--upstream-ref", help="branch with upstream AdvCiv's history, for base AdvCiv's file events (used with --write; default: the release SAS last merged)")
	args = parser.parse_args()
	if args.write:
		write_tsv(args.civ4_root, merged_release_or_exit(REPO, args.upstream_ref))
		return 0
	problems = check()
	for problem in problems:
		print("ERROR: " + problem)
	if problems:
		return 1
	print("inherited files: tsv matches the tree; the audit matches the tsv and the inherited Python imports")
	return 0


if __name__ == "__main__":
	sys.exit(main())
